def write_json(name, value):
    (HERE / name).write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")


def build():
    source = json.loads(subprocess.check_output(["git", "show", BASELINE + ":genesis/verses.json"], cwd=ROOT))
    local = json.loads((ROOT / "genesis/verses.json").read_text(encoding="utf-8"))
    units = [(str(c["chapter"]), v) for c in source["chapters"] if 31 <= c["chapter"] <= 37 for v in c["verses"]]
    local_units = [(str(c["chapter"]), v) for c in local["chapters"] if 31 <= c["chapter"] <= 37 for v in c["verses"]]
    assert units == local_units, "Local source changed: inspect before rebuild."
    assert len(units) == 244
    assert set(ROWS) == {v["reference"].split(" ", 1)[1] for _, v in units}
    assert "31:51" not in ROWS and "35:21" not in ROWS
    records = []
    for chapter, verse in units:
        ref = verse["reference"].split(" ", 1)[1]
        candidate = verse["text"]
        if ref in REPLACEMENTS:
            old, new = REPLACEMENTS[ref]
            assert candidate.count(old) == 1
            candidate = candidate.replace(old, new)
        changed = candidate != verse["text"]
        record = {
            "record_type":"focused_running_text_comparison", "review_id":"OT-008-genesis-"+ref.replace(":","-"),
            "batch_id":"OT-008", "book_id":"genesis", "reference":verse["reference"],
            "verse_anchor":verse["id"], "reading_section_id":chapter, "baseline_commit":BASELINE,
            "baseline_text":verse["text"], "candidate_text":candidate,
            "candidate_sha256":hashlib.sha256(candidate.encode("utf-8")).hexdigest(),
            "decision":"propose_revision" if changed else "retain_provisionally",
            "source":{"edition":"Rahlfs–Hanhart 2006","url":f"https://www.die-bibel.de/en/bible/LXX/GEN.{chapter}","accessed_on":"2026-11-12","running_text_read":True,"apparatus_consulted":False},
            "drafts":{"close":ROWS[ref]["close"],"spoken":candidate,"literary":candidate},
            "draft_stage_note":"Authored close working draft exposes selected Greek constructions; complete spoken/literary candidate preserves all inherited wording except separately recorded proposals. The same spoken and literary text is retained after focused comparison, without human read-aloud credit.",
            "analysis":ROWS[ref]["analysis"], "unresolved_questions":UNRESOLVED.get(ref, []),
            "review":{"reviewer":"OpenAI Codex assistant","type":"AI","scope":"Focused source-led whole-unit comparison with close working draft, not exhaustive token alignment.","all_tokens_accounted_for":False,"independent_greek":None,"human_read_aloud":None,"editorial_acceptance":None},
            "benchmark_change":False, "publication":{"staging":None,"production":None},
        }
        if changed and verse.get("poetic_line_breaks", 0):
            raise AssertionError("Provide explicit candidate_display_text for changed poetry: "+ref)
        records.append(record)
    assert len({r["verse_anchor"] for r in records}) == 244
    assert sum(r["reading_section_id"]=="32" for r in records) == 33
    changes = [r for r in records if r["decision"] == "propose_revision"]
    result={"schema_version":"1.0","batch_id":"OT-008","date":"2026-11-12","scope":"Genesis 31–37; all 244 inherited stored units, preserving the absent labels 31:51 and 35:21 and all 33 units of chapter 32.","baseline_commit":BASELINE,"status":"focused_comparison_draft_not_accepted","original_files_preserved":True,"counts":{"compared_units":244,"proposed_revisions":len(changes),"retained_units":244-len(changes),"accepted_units":0},"limitations":"AI running-text comparisons only. Full word accounting, specialist lexical evidence, apparatus/Göttingen comparison, independent human Greek review, human read-aloud, acceptance and deployment remain pending.","records":records}
    write_json("focused-reviews.json",result)
    counts={str(n):sum(r["reading_section_id"]==str(n) for r in records) for n in range(31,38)}
    write_json("sources.json",{"batch_id":"OT-008","accessed_on":"2026-11-12","edition":"Septuaginta, Alfred Rahlfs; second revised edition, Robert Hanhart, 2006, German Bible Society","method":"Complete displayed publisher running text retrieved and read; truncated initial chapter 31, 34 and 36 responses were followed by separate tail reads before analysis.","pages":[{"url":f"https://www.die-bibel.de/en/bible/LXX/GEN.{n}","stored_units":counts[str(n)],"running_text_read":True,"apparatus_consulted":False} for n in range(31,38)],"additional_sources_consulted":[],"redistribution":"Full Greek is not redistributed; public access is not claimed as a redistribution permission."})
    write_json("validation.json",{"batch_id":"OT-008","result":"pass","stored_units":244,"chapter_counts":counts,"proposal_references":[r["reference"] for r in changes],"checks":["Every inherited scoped unit appears exactly once in order","Baseline text and IDs equal pinned Git source","All close/spoken/literary drafts populated","Candidate hashes recomputed from UTF-8 text","No fabricated 31:51 or 35:21","Chapter 32 retains all 33 units including Laban farewell and sinew explanation","No inherited poetic units in assigned scope; changed poetry would require explicit display text","All original book files remain unchanged","No human review, apparatus review, acceptance or publication claimed"],"source_specific_numeric_checks":{"31:7":"ten lambs retained","31:41":"fourteen + six = twenty years; ten ewe lambs retained","32:7":"400 men","32:15":"200 female goats;20 male goats;200 sheep;20 rams","32:16":"30 nursing camels with young;40 cows;10 bulls;20 donkeys;10 foals;camel numeral scope unresolved","32:23":"two wives;two slave women;eleven children","33:3":"seven bows","33:19":"100 lambs","34:25":"third day","35:23-26":"six + two + two + two = twelve sons;birthplace summary unresolved","35:28":"Isaac180years","36:27":"four names retained","37:2":"Joseph17years","37:9":"eleven stars","37:28":"twenty gold pieces"}})
    sources = json.loads((HERE / "sources.json").read_text(encoding="utf-8"))
    sources["additional_sources_consulted"] = [{"source":"LSJ, traumatias, senses I–II","url":"https://atlas.perseus.tufts.edu/dictionaries/entry/urn%3Acite2%3Ascaife-viewer%3Adictionaries.v1%3Alsj-n104589/","consulted_by":"Root OpenAI Codex AI reviewer","accessed_on":"2026-11-12","scope":"Single entry only, reported to author; cited LXX passages not independently checked and no specialist review claimed."}]
    write_json("sources.json", sources)
    print(json.dumps(result["counts"]))


if __name__ == "__main__":
    build()
